Examplepublic class Main  
{  
    //user-defined static method  
    static void showMessage()   
    {  
        System.out.println("The static method invoked.");  
    }  
    //user-defined non-static method  
    void displayMessage()   
    {  
        System.out.println("Non-static method invoked.");  
    }  
    public static void main(String[] args)   
    {  
        //calling a static method without using the object  
        showMessage(); //called method  
        //creating an object of the class  
        Main obj = new Main();  
        //calling non-static method  
        obj.displayMessage(); //called method  
    }  
}
